const [img, cmd] = await Promise.all([
  tools.view_image({path:"/app/target.png",detail:"original"}),
  tools.exec_command({cmd:"python - <<'PY'
from rcb_client import Robot
r=Robot()
s=r.spec()
print('status',r.status())
for k in ['protocol','default_cameras','control_hz','budget','static','world','robot_spec','action_types','proprio_layout','proprio_groups','cameras','max_call_wall_s','on_service_error']:
 print('\n',k,':',s.get(k))
o=r.get_obs(depth=True)
print('\nproprio',o.meta['proprio'])
for k,v in o.last.items(): print('image',k,v.shape,v.dtype,v.min(),v.max())
for k,v in o.last_depth.items(): print('depth',k,v.shape,float(v.min()),float(v.max()))
PY",workdir:"/app",yield_time_ms:30000,max_output_tokens:6000})
]);
image(img.image_url,"original");
text(cmd.output);

